export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}''', '''/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. Retired
 * slugs still within their hold count as taken, so creation never derives one.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const now = Date.now();
  const retired = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(like(organizationSlugRetirements.slug, `${prefix}%`))
    .all();

  return [
    ...rows.map((row) => row.slug),
    ...retired
      .filter((row) => isHoldActive(row.retiredAt, now))
      .map((row) => row.slug),
  ];
}''')
