/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizationSlugRetirements,
  organizations,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** A retired slug resolves until exactly `ORG_SLUG_HOLD_DAYS` after retirement. */
function isHoldActive(retiredAt: string, now: number): boolean {
  return now < Date.parse(retiredAt) + ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
}

/**
 * Resolves a slug to a live workspace: its current slug first, then any
 * workspace still holding it as a retired slug (ADR 0005, rule 3).
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const now = Date.now();
  const retirements = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .all();

  for (const retirement of retirements) {
    if (!isHoldActive(retirement.retiredAt, now)) continue;

    const held = getDb()
      .select()
      .from(organizations)
      .where(
        and(
          eq(organizations.id, retirement.orgId),
          isNull(organizations.archivedAt),
        ),
      )
      .get();
    if (held) return toOrganization(held);
  }

  return null;
}

/**
 * True when `slug` may become `orgId`'s current slug: no other workspace,
 * live or deleted, holds it as current, and no other workspace holds it
 * retired and still within its hold.
 */
export async function isSlugAvailableFor(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const current = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug),) )
    .all();
  if (current.some((row) => row.id !== orgId)) return false;

  const now = Date.now();
  const retired = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(eq(organizationSlugRetirements.slug, slug))
    .all();
  return !retired.some(
    (row) => row.orgId !== orgId && isHoldActive(row.retiredAt, now),
  );
}

/**
 * Sets a new current slug and retires the one it replaces, in one
 * transaction. Renaming back to a slug the workspace retired ends that
 * retirement.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    tx.delete(organizationSlugRetirements)
      .where(
        and(
          eq(organizationSlugRetirements.orgId, orgId),
          eq(organizationSlugRetirements.slug, to),
        ),
      )
      .run();

    tx.insert(organizationSlugRetirements)
      .values({ orgId, slug: from, retiredAt: stamp })
      .onConflictDoUpdate({
        target: [organizationSlugRetirements.orgId, organizationSlugRetirements.slug],
        set: { retiredAt: stamp },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug: to, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Organization ${orgId} not found`);
    return toOrganization(row);
  });
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

/**
 * Settings and profile patch. `slug` is accepted for the "change workspace
 * URL" form: the form validates the slug with `slugSchema` before it gets
 * here, so the column is written as given.
 */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput & { readonly slug?: string },
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.slug === undefined ? {} : { slug: patch.slug }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. Retired
 * slugs still within their hold count as taken, so creation never derives one.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const now = Date.now();
  const retired = getDb()
    .select()
    .from(organizationSlugRetirements)
    .where(like(organizationSlugRetirements.slug, `${prefix}%`))
    .all();

  return [
    ...rows.map((row) => row.slug),
    ...retired
      .filter((row) => isHoldActive(row.retiredAt, now))
      .map((row) => row.slug),
  ];
}

