/**
 * Workspace slug renames (ADR 0005): the old slug is held for
 * `ORG_SLUG_HOLD_DAYS`, availability rules, and the event/audit side effects.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import { getDb, activityEvents } from "@/server/db";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as orgService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];
const DAY_MS = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("rename");
  other = await createTenant("rival");
});

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"], now: new Date("2026-03-01T00:00:00Z") });
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

describe("renameOrganizationSlug", () => {
  it("makes the new slug current and keeps the old one resolving during the hold", async () => {
    const before = tenant.org.slug;
    const renamed = await orgService.renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rename-two",
    });

    expect(renamed.slug).toBe("rename-two");
    expect(renamed.name).toBe(tenant.org.name);
    expect((await orgRepo.findOrgBySlug("rename-two"))?.id).toBe(tenant.org.id);
    expect((await orgRepo.findOrgBySlug(before))?.id).toBe(tenant.org.id);

    const session = await resolveActorForOrg(
      { userId: tenant.userIds.owner, email: "", activeOrgId: null, expiresAt: tenant.org.createdAt },
      before,
    );
    expect(session?.orgId).toBe(tenant.org.id);
  });

  it("releases the old slug at exactly ORG_SLUG_HOLD_DAYS", async () => {
    const old = (await orgRepo.findOrgById(tenant.org.id))!.slug;
    vi.setSystemTime(new Date(Date.now() + ORG_SLUG_HOLD_DAYS * DAY_MS - 1));
    expect((await orgRepo.findOrgBySlug(old))?.id).toBe(tenant.org.id);

    vi.setSystemTime(new Date(Date.now() + 1));
    expect(await orgRepo.findOrgBySlug(old)).toBeNull();
  });

  it("refuses a slug another workspace holds retired, and creation derives around it", async () => {
    const otherSlug = other.org.slug;
    await orgService.renameOrganizationSlug(other.actors.owner, {
      orgId: other.org.id,
      slug: "rival-two",
    });

    await expect(
      orgService.renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: otherSlug,
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    const created = await orgService.createOrganization(tenant.userIds.owner, {
      name: "Rival again",
      slug: otherSlug,
      plan: "free",
    });
    expect(created.slug).toBe(`${otherSlug}-2`);
  });

  it("lets the workspace take back its own retired slug and ends that hold", async () => {
    const current = (await orgRepo.findOrgById(tenant.org.id))!.slug;
    const original = "rename";
    const back = await orgService.renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: original,
    });
    expect(back.slug).toBe(original);
    expect((await orgRepo.findOrgBySlug(current))?.id).toBe(tenant.org.id);
    expect((await orgRepo.findOrgBySlug(current))?.slug).toBe(original);
  });

  it("is a no-op for the current slug: nothing is written or published", async () => {
    const seen: unknown[] = [];
    detachers.push(subscribe("organization.slug_changed", (payload) => void seen.push(payload)));
    const current = (await orgRepo.findOrgById(tenant.org.id))!;
    const before = getDb().select().from(activityEvents).all().length;

    const result = await orgService.renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: current.slug,
    });

    expect(result).toEqual(current);
    expect(seen).toHaveLength(0);
    expect(getDb().select().from(activityEvents).all().length).toBe(before);
